# Break My Fix finding 1, generated by Tracefix: yaml_load raises TypeError.
# Property (issue): A string that looks like 'Foo:' (a single word followed by a colon, optionally surrounded by whitespace) must not be turned into a dict; it is returned unchanged as the string
# Quote: str argument is mistaken as a dict if it looks like 'Foo:'
# Run it with pytest: it fails for as long as the code breaks this property.

import re

from jsonargparse.loaders_dumpers import yaml_load


def test_break_my_fix_1() -> None:
    stream = 'null:'
    # The property applies to this input: isinstance(stream, str) and re.fullmatch(r'\s*[A-Za-z0-9_]+:\s*', stream) is not None
    result = yaml_load(stream=stream)
    assert (isinstance(result, str))
    assert result == (stream)
